using System;using System.Collections;using System.IO;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using UnityEditor;
namespace HorrorGame.Tests{
 [Category("Whistle")]
 public sealed partial class WhistlePlayTests{
  BeforeDemolitionChapterFixture f;WhistleSystem s;WhistleConfig config;BeforeDemolitionMirrorFlow mirror;
  [UnitySetUp] public IEnumerator Setup(){f=new BeforeDemolitionChapterFixture(BeforeDemolitionMirrorFlow.ChapterId,new[]{new StoryMilestoneDefinition{id=BeforeDemolitionMirrorFlow.SeenSignal},new StoryMilestoneDefinition{id=BeforeDemolitionMirrorFlow.BrokenSignal},new StoryMilestoneDefinition{id=BeforeDemolitionMirrorFlow.ChoiceSignal},new StoryMilestoneDefinition{id=BeforeDemolitionMirrorFlow.FinishSignal}});var testScene=f.root.scene;testScene.name="SchoolCEEP";config=ScriptableObject.CreateInstance<WhistleConfig>();s=f.root.AddComponent<WhistleSystem>();s.game=f.game;s.config=config;s.enabled=false;f.whistle.system=s;mirror=f.Child("Mirror").AddComponent<BeforeDemolitionMirrorFlow>();mirror.game=f.game;mirror.whistle=f.whistle;mirror.mirrorVolume=f.Volume("Volume",new Vector3(0,1,0),new Vector3(6,5,6));mirror.mirrorPlane=f.Child("Plane").transform;mirror.mirrorPlane.position=new Vector3(0,1.64f,2);mirror.glassVisual=f.Child("Glass");mirror.revealVisual=f.Child("Reveal");yield return f.Activate();s.Restore(null);Assert.That(s.CanUse,Is.True);}
  WhistleResponder Responder(){var r=f.Child("Target").AddComponent<WhistleResponder>();r.responderId="test.once";r.transform.position=f.camera.transform.position+Vector3.forward*2;r.range=10;return r;}
  void Tick(WhistleResponder r,float dt){typeof(WhistleResponder).GetMethod("Tick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(r,new object[]{dt,true});}
  void Blow(bool hold){s.State.cooldownRemaining=0;if(!s.Equipped)s.ToggleEquipped();Assert.That(s.Press(),Is.True);if(!hold)s.Release();s.Advance(1.3f);if(hold){for(int i=0;i<31;i++)s.Advance(.1f);s.Release();s.Advance(.1f);}s.Advance(.3f);}
  [UnityTest] public IEnumerator OnePressOneTapWithoutReleaseAndCooldown(){int taps=0,holds=0;s.Blown+=c=>{if(c.kind==WhistleKind.Tap)taps++;else holds++;};Blow(false);Assert.That(taps,Is.EqualTo(1));Assert.That(s.BlowTap(),Is.False);Assert.That(s.State.hesitated&&s.State.learnedTap,Is.True);s.State.cooldownRemaining=0;Blow(true);Assert.That(holds,Is.Zero);Assert.That(taps,Is.EqualTo(2));Assert.That(s.State.learnedHold,Is.False);Assert.That(s.Busy,Is.False);Assert.That(f.game.IsBlackingOut,Is.False);yield return null;}
  [UnityTest]public IEnumerator OnceResponderFlagAndSaveRoundTrip(){var r=Responder();r.onceOnly=true;int count=0;r.onResponse.AddListener(()=>count++);Assert.That(s.BlowTap(),Is.True);Tick(r,5);Assert.That(count,Is.EqualTo(1));s.State.cooldownRemaining=0;Assert.That(s.BlowTap(),Is.True);Tick(r,10);Assert.That(count,Is.EqualTo(1));var saved=JsonUtility.FromJson<WhistleState>(JsonUtility.ToJson(s.Capture()));s.Restore(saved);Assert.That(s.HasResponded(r.responderId),Is.True);s.Restore(null);Assert.That(s.State.pickupLinePlayed,Is.True);r.requiredFlag="not.present";Assert.That(r.CanHear(new WhistleContext(s,f.camera.transform.position,Vector3.forward,WhistleKind.Tap,0,99,"fixture","room")),Is.False);yield return null;}
  [UnityTest]public IEnumerator PauseInspectionPcPhoneAndCutsceneBlockCommonModalGate(){foreach(var label in new[]{"inspection","PC","phone"}){Assert.That(f.game.BeginInspection(),Is.True,label);Assert.That(s.CanUse||s.BlowTap(),Is.False,label);f.game.EndInspection();yield return null;yield return null;}f.game.Pause();Assert.That(s.CanUse||s.BlowTap(),Is.False);f.game.Resume();yield return null;yield return null;f.game.DisableControl();Assert.That(s.CanUse||s.BlowTap(),Is.False);f.game.EnableControl();yield return null;yield return null;Assert.That(s.CanUse,Is.True);}
  [UnityTest]public IEnumerator LegacyHoldNeverCracksMirror(){var r=Responder();r.role=WhistleResponseRole.Mirror;r.mirror=mirror;r.respondToHold=true;for(int i=0;i<30;i++)r.OnWhistleHold(new WhistleContext(s,f.camera.transform.position,Vector3.forward,WhistleKind.Hold,i*.1f,2,"fixture","mirror"),i*.1f);Assert.That(mirror.Data.whistleCrack,Is.Zero);Assert.That(mirror.Data.stage,Is.Zero);Assert.That(mirror.BreakMirror(),Is.False);yield return null;}
  [UnityTest]public IEnumerator StressOnlyCoolsAndChapterFiveSixReduceCost(){s.State.cooldownRemaining=0;Assert.That(s.BlowTap(),Is.True);Assert.That(s.State.tension,Is.EqualTo(.1f).Within(.001f));s.State.Cool(10,config);Assert.That(s.State.tension,Is.Zero);Assert.That(f.game.IsBlackingOut,Is.False);Assert.That(f.game.State,Is.EqualTo(GameState.Playing));yield return null;}
  [UnityTest]public IEnumerator DispatchAllocationMeasurement(){var r=Responder();r.onceOnly=false;r.delay=100;for(int i=0;i<20;i++){s.State.cooldownRemaining=0;s.BlowTap();}var watch=new System.Diagnostics.Stopwatch();long total=0,max=0,ticks=0,peakTicks=0;for(int i=0;i<100;i++){s.State.cooldownRemaining=0;long before=GC.GetAllocatedBytesForCurrentThread();watch.Restart();s.BlowTap();watch.Stop();long bytes=GC.GetAllocatedBytesForCurrentThread()-before;total+=bytes;max=Math.Max(max,bytes);ticks+=watch.ElapsedTicks;peakTicks=Math.Max(peakTicks,watch.ElapsedTicks);}var result=new{scope="Warm isolated synchronous BlowTap + registry dispatch, no audio manager/HUD/whole-frame GPU measurement",samples=100,meanBytes=total/100d,peakBytes=max,meanMilliseconds=ticks*1000d/System.Diagnostics.Stopwatch.Frequency/100,peakMilliseconds=peakTicks*1000d/System.Diagnostics.Stopwatch.Frequency};File.WriteAllText("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/work/Whistle20261031/performance.json",JsonUtility.ToJson(new Perf{meanBytes=(float)result.meanBytes,peakBytes=max,meanMs=(float)result.meanMilliseconds,peakMs=(float)result.peakMilliseconds}));Debug.Log("Whistle dispatch mean bytes="+result.meanBytes+" peak="+max+" mean ms="+result.meanMilliseconds);Assert.That(s.State.Valid,Is.True);yield return null;}
  [UnityTest]public IEnumerator CancelCannotBypassAnEmittedBlowCooldown(){s.ToggleEquipped();Assert.That(s.Press(),Is.True);s.Advance(1.3f);Assert.That(s.State.learnedTap,Is.True);s.Cancel();Assert.That(s.State.cooldownRemaining,Is.GreaterThan(0));Assert.That(s.BlowTap(),Is.False);s.State.Cool(config.cooldown+1,config);Assert.That(s.BlowTap(),Is.True);yield return null;}
  [Serializable]class Perf{public float meanBytes,meanMs,peakMs;public long peakBytes;}
  [UnityTearDown]public IEnumerator Cleanup(){if(f!=null)yield return f.Dispose();if(config)UnityEngine.Object.Destroy(config);}
 }
}
